const products=window.catalog||[];
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const priceText=p=>p.referencePrice===null?'Reference price unavailable':`${money(p.referencePrice)} USD reference`;
const imageHTML=p=>p.image?`<img class="catalog-image" src="${esc(p.image)}" alt="${esc(p.name)} — AI-styled from linked source photo" width="1024" height="1024">`:'<div class="catalog-image image-pending"><span>PRODUCT PHOTO<br>AWAITING VERIFICATION</span></div>';
const storageKey='fubao-reference-bag-v1';let bag={};try{const saved=JSON.parse(localStorage.getItem(storageKey)||'{}');if(saved&&typeof saved==='object'&&!Array.isArray(saved))for(const p of products){const q=saved[p.id];if(Number.isInteger(q)&&q>0)bag[p.id]=Math.min(q,99)}}catch{}
let toastTimer;function announce(message){const el=document.querySelector('#status');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),2600)}
function saveBag(){try{localStorage.setItem(storageKey,JSON.stringify(bag))}catch{}document.querySelector('#bag-count').textContent=Object.values(bag).reduce((a,b)=>a+b,0)}
function addToBag(id){if((bag[id]||0)>=99){announce('Maximum 99 of each reference.');return}bag[id]=(bag[id]||0)+1;saveBag();announce(`${products.find(p=>p.id===id).name} saved to your reference list`)}
function renderProducts(category='All'){let count=0;for(const card of document.querySelectorAll('#products .product-card')){card.hidden=category!=='All'&&card.dataset.category!==category;if(!card.hidden)count++}document.querySelector('#results-count').textContent=`${count} PIECES`}
document.querySelector('.filters').addEventListener('click',e=>{const button=e.target.closest('[data-filter]');if(!button)return;for(const b of document.querySelectorAll('[data-filter]')){const selected=b===button;b.classList.toggle('active',selected);b.setAttribute('aria-pressed',selected)}renderProducts(button.dataset.filter)});
const detail=document.querySelector('#product-dialog'),bagDialog=document.querySelector('#bag-dialog');let returnFocus;
function openDialog(dialog){returnFocus=document.activeElement;dialog.showModal()}
for(const dialog of [detail,bagDialog]){dialog.addEventListener('close',()=>{if(returnFocus?.isConnected)returnFocus.focus()});dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});dialog.addEventListener('keydown',e=>{if(e.key!=='Tab')return;const focusable=[...dialog.querySelectorAll('button,a[href],input,select,textarea,[tabindex="0"]')].filter(el=>!el.disabled);const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}})}
document.addEventListener('click',e=>{const close=e.target.closest('[data-close]');if(close){close.closest('dialog').close();return}const add=e.target.closest('[data-add]');if(add){addToBag(add.dataset.add);return}const trigger=e.target.closest('[data-detail]');if(trigger){const p=products.find(p=>p.id===trigger.dataset.detail);document.querySelector('#detail-content').innerHTML=`<div class="detail-grid">${imageHTML(p)}<div class="detail-copy"><p class="eyebrow orange-text">${esc(p.category.toUpperCase())} / RESEARCH SELECTION</p><h2 id="detail-title">${esc(p.name)}</h2><p class="detail-price">${priceText(p)}</p><p>${esc(p.description)}</p><p>Amazon reference recorded October 25, 2026, converted at ¥150 = US$1. Not a live quote or FUBAO selling price. AI-styled images may differ in fine detail.</p><p><a class="text-link" href="products/${p.id}.html">Full details & source ↗</a></p><button class="button orange" data-add="${p.id}">SAVE REFERENCE <span>+</span></button></div></div>`;openDialog(detail)}});
function renderBag(){const chosen=products.filter(p=>bag[p.id]);document.querySelector('#bag-items').innerHTML=chosen.length?chosen.map(p=>`<div class="bag-row">${imageHTML(p)}<div><h3>${esc(p.name)}</h3><p>${priceText(p)} each</p><div class="quantity"><button data-quantity="${p.id}" data-change="-1" aria-label="Decrease ${esc(p.name)} quantity">−</button><span aria-label="Quantity">${bag[p.id]}</span><button data-quantity="${p.id}" data-change="1" aria-label="Increase ${esc(p.name)} quantity" ${bag[p.id]>=99?'disabled':''}>+</button><button class="remove" data-remove="${p.id}" aria-label="Remove ${esc(p.name)}">Remove</button></div></div></div>`).join(''):'<div class="empty">Your next signature is waiting.<br>Explore the collection to start your rotation.</div>';document.querySelector('#bag-total').textContent=money(chosen.reduce((sum,p)=>sum+(p.referencePrice||0)*bag[p.id],0))+(chosen.some(p=>p.referencePrice===null)?' + unpriced items':'')}
document.querySelector('#bag-open').addEventListener('click',()=>{renderBag();openDialog(bagDialog)});
bagDialog.addEventListener('click',e=>{const q=e.target.closest('[data-quantity]'),r=e.target.closest('[data-remove]');if(!q&&!r)return;if(q){const id=q.dataset.quantity;bag[id]=Math.min(99,bag[id]+Number(q.dataset.change));if(bag[id]<=0)delete bag[id]}else delete bag[r.dataset.remove];saveBag();renderBag();const next=q?[...bagDialog.querySelectorAll('[data-quantity]')].find(b=>b.dataset.quantity===q.dataset.quantity&&b.dataset.change===q.dataset.change&&!b.disabled):null;(next||bagDialog.querySelector('[data-close]')).focus()});
const menu=document.querySelector('#menu-toggle'),nav=document.querySelector('#navigation');menu.addEventListener('click',()=>{const expanded=menu.getAttribute('aria-expanded')==='true';menu.setAttribute('aria-expanded',!expanded);nav.classList.toggle('open',!expanded)});nav.addEventListener('click',e=>{if(e.target.closest('a')){menu.setAttribute('aria-expanded','false');nav.classList.remove('open')}});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav.classList.contains('open')){nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.focus()}});
renderProducts();saveBag();
